using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using Object=UnityEngine.Object;
public static class ImportGuardRole {
 public static object Main(){if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Edit required");const string folder="Assets/ShooterSurvival/Models/Chapters/Chapters45/DetailedCharacters20261003/CH01/";if(AssetDatabase.LoadAssetAtPath<AnimationClip>(folder+"guard.anim")!=null)throw new Exception("Already imported");AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);var ai=(ModelImporter)AssetImporter.GetAtPath(folder+"guard.fbx");ai.animationType=ModelImporterAnimationType.Generic;ai.avatarSetup=ModelImporterAvatarSetup.CopyFromOther;ai.sourceAvatar=AssetDatabase.LoadAllAssetsAtPath(folder+"body.fbx").OfType<Avatar>().First();ai.animationCompression=ModelImporterAnimationCompression.Off;ai.materialImportMode=ModelImporterMaterialImportMode.None;ai.importAnimation=true;ai.SaveAndReimport();var source=AssetDatabase.LoadAllAssetsAtPath(folder+"guard.fbx").OfType<AnimationClip>().First(c=>!c.name.StartsWith("__preview")&&c.length>.05f);var clip=Object.Instantiate(source);clip.name="guard";foreach(var b in AnimationUtility.GetCurveBindings(clip))if(b.propertyName.StartsWith("m_LocalScale"))AnimationUtility.SetEditorCurve(clip,b,null);AssetDatabase.CreateAsset(clip,folder+"guard.anim");var prefab=PrefabUtility.LoadPrefabContents(folder+"CH01.prefab");try{var model=prefab.GetComponentInChildren<Animator>().gameObject;var hip=model.transform.Find("Armature/Hips");var curves=new[]{new AnimationCurve(),new AnimationCurve(),new AnimationCurve()};for(int i=0;i<=Mathf.CeilToInt(clip.length*30);i++){float t=Mathf.Min(clip.length,i/30f);clip.SampleAnimation(model,t);float bottom=float.PositiveInfinity;foreach(var skin in model.GetComponentsInChildren<SkinnedMeshRenderer>()){var mesh=new Mesh();skin.BakeMesh(mesh,false);foreach(var v in mesh.vertices)bottom=Mathf.Min(bottom,prefab.transform.InverseTransformPoint(skin.transform.TransformPoint(v)).y);Object.DestroyImmediate(mesh);}var unit=hip.parent.InverseTransformVector(prefab.transform.TransformVector(Vector3.up));var p=hip.localPosition+unit*(.008f-bottom);for(int axis=0;axis<3;axis++)curves[axis].AddKey(t,p[axis]);}for(int axis=0;axis<3;axis++)AnimationUtility.SetEditorCurve(clip,EditorCurveBinding.FloatCurve("Armature/Hips",typeof(Transform),"m_LocalPosition."+"xyz"[axis]),curves[axis]);EditorUtility.SetDirty(clip);AssetDatabase.SaveAssets();return new{path=folder+"guard.anim",source=source.name,clip.length,sourceOwnAvatar=true};}finally{PrefabUtility.UnloadPrefabContents(prefab);}}
}
